tool_input.content:
const fs=require('fs');
const s=fs.readFileSync('/home/zmhel/gitrepos/learn-ai/eval01/runs/.gen-work/u14/game.html','utf8');
const m=s.match(/<script>([\s\S]*)<\/script>/);
if(!m){console.log('NO SCRIPT BLOCK');process.exit(1);}
new Function(m[1]); // syntax check of the whole script including UI code
console.log('SYNTAX OK, script chars:',m[1].length);
const logic=m[1].split('/*==LOGIC-END==*/')[0];
(0,eval)(logic);
const res=runTests();
for(const r of res)console.log((r[1]?'PASS':'FAIL')+'  '+r[0]);
console.log(res.filter(r=>r[1]).length+'/'+res.length+' passed');
const b1=runBenchmark(1337,200), b2=runBenchmark(1337,200);
console.log('bench hash1',b1.hash,'hash2',b2.hash,'match:',b1.hash===b2.hash);
console.log('bench: turn',b1.turn,'pop',b1.pop,'research',b1.research,'storms',b1.storms,'score',b1.score);
console.log('outcome:',b1.over);
// extra: does the greedy policy WIN a normal 60-turn game? (winnability probe)
const g=newGame(1337);
for(let t=0;t<60&&!g.over;t++)policyTurn(g,{});
console.log('60-turn policy run => over:',JSON.stringify(g.over),'pop:',pop(g));
